            try:
                # X button HIDES the panel — it never kills the pipeline
                self.protocol("WM_DELETE_WINDOW", self._gui_hide_window)
            except Exception:
                pass
            try:
                self.withdraw()   # start hidden — Alt+Ctrl+Y shows it
            except Exception:
                pass
